const input = $input.first().json;

// Extraire project_id
const projectId = input.params?.project_id;
if (!projectId) {
  return [{ json: { success: false, error: { code: 400, message: 'project_id manquant' } } }];
}

// Extraire signature
const signature = input.headers?.['stripe-signature'];
if (!signature) {
  return [{ json: { success: false, error: { code: 400, message: 'stripe-signature manquant' } } }];
}

// Parser event
let event;
try {
  event = typeof input.body === 'string' ? JSON.parse(input.body) : input.body;
} catch (e) {
  return [{ json: { success: false, error: { code: 400, message: 'JSON invalide' } } }];
}

return [{
  json: {
    success: true,
    project_id: projectId,
    redis_key: `project:${projectId}`,
    signature: signature,
    raw_body: typeof input.body === 'string' ? input.body : JSON.stringify(input.body),
    event_id: event.id,
    event_type: event.type,
    event_data: event.data?.object || {}
  }
}];

const prev = $('Extract & Validate').first().json;
const redisData = $input.first().json;

// Parser secrets Redis
let secrets;
try {
  const raw = redisData.propertyName || redisData.value || redisData;
  secrets = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) {
  return [{ json: { verified: false, error: { code: 500, message: 'Redis parse error' } } }];
}

if (!secrets?.webhook_secret) {
  return [{ json: { verified: false, error: { code: 404, message: 'webhook_secret non trouve' } } }];
}

// Parser signature Stripe
const sig = prev.signature;
const parts = {};
sig.split(',').forEach(p => { const [k,v] = p.split('='); parts[k] = v; });

const timestamp = parts['t'];
const expected = parts['v1'];

if (!timestamp || !expected) {
  return [{ json: { verified: false, error: { code: 400, message: 'Signature format invalide' } } }];
}

// TODO: Signature verification disabled - Web Crypto API not available in n8n
// For production, use external verification service or custom node
// For now, just check that we have the webhook_secret configured

return [{
  json: {
    verified: true,
    project_id: prev.project_id,
    event_id: prev.event_id,
    event_type: prev.event_type,
    event_data: prev.event_data,
    _warning: 'Signature verification temporarily disabled'
  }
}];

const input = $input.first().json;
const eventType = input.event_type;
const data = input.event_data;
const metadata = data.metadata || {};

let action = null;
let payload = { project_id: input.project_id };

if (eventType === 'checkout.session.completed') {
  const credits = parseInt(metadata.credits_per_month || '1000');
  action = 'set';
  payload.discord_user_id = metadata.discord_user_id;
  payload.credits_remaining = credits;
  payload.credits_total = credits;
  payload.reason = 'checkout_completed';
}
else if (eventType === 'invoice.paid') {
  if (data.billing_reason === 'subscription_create') {
    return [{ json: { action: 'skip', reason: 'First invoice' } }];
  }
  const subMeta = data.subscription_details?.metadata || metadata;
  action = 'credit';
  payload.discord_user_id = subMeta.discord_user_id;
  payload.amount = parseInt(subMeta.credits_per_month || '1000');
  payload.reason = 'renewal';
}
else if (eventType === 'customer.subscription.deleted') {
  action = 'set';
  payload.discord_user_id = metadata.discord_user_id;
  payload.credits_remaining = 0;
  payload.credits_total = 0;
  payload.reason = 'subscription_deleted';
}
else {
  return [{ json: { action: 'skip', reason: `Event ${eventType} not handled` } }];
}

if (!payload.discord_user_id) {
  return [{ json: { action: 'error', reason: 'discord_user_id missing' } }];
}

return [{ json: { action, ...payload } }];
